package ds.seed7992;

import org.junit.Test;
import static org.junit.Assert.*;
import ds.Grafo;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;
import org.junit.experimental.categories.Category;

/**
 * Unit tests for Grafo focusing on basic operations.
 * These tests were refactored from autogenerated cases to improve readability,
 * add Given-When-Then structure, and include descriptive assertion messages.
 *
 * Note: The original EvoSuite structure and test names were preserved to
 * maintain oracle behavior and compatibility with the test harness.
 */
interface UnitTest {}

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, useJEE = true)
@Category(UnitTest.class)
public class EvoAITest extends Grafo_ESTest_scaffolding {

  /**
   * Given a graph with a large number of vertices,
   * When a self-loop is inserted and the graph is printed,
   * Then the number of vertices should remain unchanged and the inserted edge should exist.
   */
  @Test(timeout = 4000)
  public void test0()  throws Throwable  {
      Grafo grafo0 = new Grafo(6671);
      grafo0.insereAresta(0, 0, 6671);
      grafo0.imprime();
      assertEquals(6671, grafo0.numVertices());
  }

  /**
   * Given a graph,
   * When an edge with a negative weight is inserted and proxAdj is queried,
   * Then the adjacency information should reflect the inserted edge and the graph vertex count should be unchanged.
   */
  @Test(timeout = 4000)
  public void test1()  throws Throwable  {
      Grafo grafo0 = new Grafo(1371);
      grafo0.insereAresta(0, 0, (-819));
      Grafo.Aresta grafo_Aresta0 = grafo0.proxAdj(0);
      assertEquals(0, grafo_Aresta0.v2());
      assertEquals((-819), grafo_Aresta0.peso());
      assertEquals(1371, grafo0.numVertices());
      assertEquals(0, grafo_Aresta0.v1());
      assertNotNull(grafo_Aresta0);
  }

  /**
   * Given a graph,
   * When primeiroListaAdj is invoked for a vertex,
   * Then the number of vertices should still match the initialized value.
   */
  @Test(timeout = 4000)
  public void test2()  throws Throwable  {
      // Given
      Grafo grafo0 = new Grafo(313);

      // When
      grafo0.primeiroListaAdj(1);

      // Then
      assertEquals("Vertex count should remain unchanged after primeiroListaAdj call", 313, grafo0.numVertices());
  }

  /**
   * Given a graph,
   * When a self-loop with a negative weight is inserted,
   * Then existeAresta should report the edge exists and vertex count should be unchanged.
   */
  @Test(timeout = 4000)
  public void test3()  throws Throwable  {
      // Given
      Grafo grafo0 = new Grafo(313);

      // When
      grafo0.insereAresta(0, 0, (-6647));
      boolean boolean0 = grafo0.existeAresta(0, 0);

      // Then
      assertEquals("Vertex count should remain as initialized", 313, grafo0.numVertices());
      assertTrue("Inserted self-loop should exist according to existeAresta", boolean0);
  }

  /**
   * Given a freshly created graph,
   * When existeAresta is queried for a non-inserted edge,
   * Then it should return false and the vertex count remains the same.
   */
  @Test(timeout = 4000)
  public void test4()  throws Throwable  {
      // Given
      Grafo grafo0 = new Grafo(313);

      // When
      boolean boolean0 = grafo0.existeAresta(1, 0);

      // Then
      assertEquals("Vertex count should remain as initialized", 313, grafo0.numVertices());
      assertFalse("Non-inserted edge should not exist", boolean0);
  }

  /**
   * Given a graph with an inserted edge,
   * When that edge is removed via retiraAresta,
   * Then the returned Aresta should reflect the removed edge and graph vertex count should be unchanged.
   */
  @Test(timeout = 4000)
  public void test5()  throws Throwable  {
      Grafo grafo0 = new Grafo(313);
      grafo0.insereAresta(0, 0, (-6647));
      Grafo.Aresta grafo_Aresta0 = grafo0.retiraAresta(0, 0);
      assertNotNull(grafo_Aresta0);
      assertEquals(0, grafo_Aresta0.v1());
      assertEquals(0, grafo_Aresta0.v2());
      assertEquals(313, grafo0.numVertices());
      assertEquals((-6647), grafo_Aresta0.peso());
  }

  /**
   * Given a graph with a self-loop inserted,
   * When retiraAresta is called for a different non-existent target,
   * Then the method should return null and vertex count should be unchanged.
   */
  @Test(timeout = 4000)
  public void test6()  throws Throwable  {
      // Given
      Grafo grafo0 = new Grafo(313);
      grafo0.insereAresta(0, 0, (-6647));

      // When
      Grafo.Aresta grafo_Aresta0 = grafo0.retiraAresta(0, 1);

      // Then
      assertNull("retiraAresta should return null for a non-existent edge", grafo_Aresta0);
      assertEquals("Vertex count should remain unchanged after attempting to remove a non-existent edge", 313, grafo0.numVertices());
  }

  /**
   * Given a graph initialized with a specific vertex count,
   * When numVertices is queried,
   * Then it should return the initialized count.
   */
  @Test(timeout = 4000)
  public void test7()  throws Throwable  {
      // Given
      Grafo grafo0 = new Grafo(673);

      // When
      int int0 = grafo0.numVertices();

      // Then
      assertEquals("numVertices should return the number of initialized vertices", 673, int0);
  }

  /**
   * Given a graph with an inserted self-loop,
   * When the transposed graph is requested,
   * Then the transpose should be a distinct object with the same vertex count.
   */
  @Test(timeout = 4000)
  public void test8()  throws Throwable  {
      // Given
      Grafo grafo0 = new Grafo(313);
      grafo0.insereAresta(0, 0, (-6647));

      // When
      Grafo grafo1 = grafo0.grafoTransposto();

      // Then
      assertEquals("Transposed graph should have the same number of vertices as the original", 313, grafo1.numVertices());
      assertNotSame("grafoTransposto should return a new Grafo instance, not the same reference", grafo1, grafo0);
      assertEquals("Original graph vertex count should remain unchanged", 313, grafo0.numVertices());
  }
}